//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:				HE_100F_Last_Fault
//	CREATOR:			Helgevold - William Veim
//
// REQUIREMENTS: Vacon 100F
// DESCRTIPTION: 	Generer en string med siste feilkode i frekvensomformeren
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN						DESCRIPTION
//	 1.0.0				2025-03-27		William Veim			Initial release
//	 1.1.0				2026-02-05		William Veim			Updated according to site testing
//
//================================================================================================================================


// Initilize
Wrk_FaultValue := WORD_TO_UINT(Inp_LastFault);
Wrk_FaultString := '';
Wrk_FaultDescription := '';
WRK_FaultCode := '';

Wrk_LFT_Value := INT_TO_STRING(Wrk_FaultValue);

CASE Wrk_FaultValue OF
	
	0 :
		WRK_FaultCode := '';
		Wrk_FaultDescription := 'No error detected';
		
	1 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Overcurrent';
	
	2 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Overvoltage';
	
	3 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Earth fault';
	
	5 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Charging switch';
	
	7 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Saturation';
	
	8 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'System fault';
	
	9 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Undervoltage';
	
	10 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Input phase';

	11 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Output phase supervision';
	
	13 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Drive undertemperature';
	
	14 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Drive overtemperature';
	
	15 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Motor stall';
	
	16 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Motor overtamperature';
	
	17 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Motor underload';
	
	18 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Unbalanse';

	19 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Power overload';
	
	25 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Motor control fault';
	
	26 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Start up prevented';
	
	29 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'ATEX thermistor';
	
	30 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Safe off';
	
	32 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Fan cooling';
	
	33 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Fire mode enabled';
	
	37 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Device changed';
	
	38 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Device added';
	
	39 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Device removed';
	
	40 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Device unknown';
	
	41 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'IGBT temperature';
	
	44 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Device changed';
	
	45 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Device added';
	
	46 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Real time clock';
	
	47 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Software updated';
	
	50 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'AI low fault';
	
	51 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Device external fault';
	
	52 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Keypad communication fault';
	
	53 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Fieldbus communication fault';
	
	54 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Option slot fault';
	
	57 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Indentification fault';
	
	63 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Quik stop';
	
	65 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'PC communication fault';
	
	66 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Thermistor input fault';
	
	68 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Maintenance counter alarm';
	
	69 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Fieldbus mapping error';
	
	70 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Baseline run failed';

	71 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Stator winding fault';
	
	76 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Start prevented';
	
	77 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Too many connections';
	
	78 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Identification ongoing';
	
	100 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Soft fill timeout';

	101 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Feedback supervision fault (PID1)';
	
	105 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Feedback supervision fault (ExtPID)';
	
	109 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Input pressure supervision';
	
	111 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Temperature fault 1';
	
	112 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Temperature fault 2';
	
	113 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Pump running time';
	
	117 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Flow switch';
	
	118 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'AHF over temp';
	
	119 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Auto cleaning';
	
	300 :
	WRK_FaultCode := '';
	Wrk_FaultDescription := 'Unsupported config';
		
ELSE
	WRK_FaultCode := '???';
	Wrk_FaultDescription := 'Unknown fault';

END_CASE;

// Add fault ID
IF TestABit(In:=Cfg_Composition, Pos:=0) THEN
	Wrk_FaultString := CONCAT(Wrk_FaultString, Wrk_LFT_Value);
END_IF;	

// Add Fault Code
IF TestABit(In:=Cfg_Composition, Pos:=1) THEN
	IF LEN(WRK_FaultCode) > 0 THEN
		Wrk_FaultString := CONCAT(Wrk_FaultString, Cfg_Delimiter);
	END_IF;
	Wrk_FaultString := CONCAT(Wrk_FaultString, WRK_FaultCode);
END_IF;

// Add Fault Description
IF TestABit(In:=Cfg_Composition, Pos:=2) THEN
	IF LEN(Wrk_FaultDescription) > 0 THEN
		Wrk_FaultString := CONCAT(Wrk_FaultString, Cfg_Delimiter);
	END_IF;
	Wrk_FaultString := CONCAT(Wrk_FaultString, Wrk_FaultDescription);
END_IF;

HE_100F_Drive_Fault := Wrk_FaultString;
